package dns

import (
	"crypto/subtle"
	"encoding/binary"
	"hash/fnv"
	"net"
	"time"
)

// Cookie option field sizes as used by CookieHandler.
const (
	// CookieClientLen is the required length of a client cookie in bytes (RFC 7873 Section 4).
	CookieClientLen = 8
	// CookieServerLen is the length of the server cookies generated and
	// verified by CookieHandler, using the RFC 9018 Section 4.2 format.
	CookieServerLen = 16
	// CookieVersion is the server cookie version generated by CookieHandler.
	CookieVersion = 1

	cookieHashLen = CookieServerLen - 8 // version(1) | reserved(3) | timestamp(4) | hash(8)

	// RFC 7873 Section 4: a server cookie is 8 to 32 bytes.
	cookieMaxLen = CookieClientLen + 32

	cookieDefaultLifetime = time.Hour
)

var (
	// ErrCookieSecret is returned when a server cookie cannot be generated
	// because no secrets are configured.
	ErrCookieSecret error = &Error{err: "no cookie secrets defined"}
	// ErrCookieClient is returned when a client cookie does not have the
	// required length of CookieClientLen bytes.
	ErrCookieClient error = &Error{err: "client cookie must be 8 bytes"}
	// ErrCookieAddr is returned when the client IP address is not a valid
	// IPv4 or IPv6 address.
	ErrCookieAddr error = &Error{err: "invalid client IP address"}
)

// CookieStatus describes the result of validating the COOKIE option of a
// request with CookieHandler.Validate. It only reports a verdict; deciding
// whether to answer with RcodeBadCookie and which response size policy to
// apply (RFC 9018 Section 5.2) is left to the caller.
type CookieStatus int

const (
	// CookieAbsent indicates the request did not contain a COOKIE option.
	CookieAbsent CookieStatus = iota
	// CookieClientOnly indicates a well-formed client cookie without a
	// server cookie. The client is asking to learn a server cookie.
	CookieClientOnly
	// CookieValid indicates a client cookie with a server cookie that
	// verifies against the key ring, is bound to the source address and is
	// within its lifetime.
	CookieValid
	// CookieExpired indicates a well-formed server cookie whose timestamp
	// is older than the configured lifetime.
	CookieExpired
	// CookieInvalid indicates a malformed cookie, a hash mismatch or a
	// cookie bound to a different source address.
	CookieInvalid
)

func (s CookieStatus) String() string {
	switch s {
	case CookieAbsent:
		return "absent"
	case CookieClientOnly:
		return "client only"
	case CookieValid:
		return "valid"
	case CookieExpired:
		return "expired"
	case CookieInvalid:
		return "invalid"
	}
	return "unknown"
}

// CookieHandler generates and validates RFC 9018 server cookies. It is
// stateless: no per-client state is kept, all information needed to verify
// a cookie is carried inside the cookie itself.
//
// The server cookie follows the format of RFC 9018 Section 4.2:
//
//	Version (1) | Reserved (3) | Timestamp (4) | Hash (8)
//
// The Hash is FNV-1a 64 (the example algorithm of RFC 9018 Appendix A.1)
// over, in order: the client cookie, Version, Reserved, Timestamp, the
// client IP address (4 bytes for IPv4, 16 for IPv6) and the server secret.
//
// Secrets is a key ring: Secrets[0] signs newly generated cookies while all
// entries are tried during validation, allowing key rotation. Secrets must
// not be modified while the handler is in use; to rotate keys, assign a new
// slice under the caller's synchronization. Secret material is never
// included in returned errors.
//
// A CookieHandler is safe for concurrent use as long as its fields are not
// modified.
type CookieHandler struct {
	// Secrets is the key ring. Secrets[0] is used to generate new server
	// cookies, all secrets are used to validate them.
	Secrets [][]byte
	// Lifetime is how long a server cookie stays valid. If zero or
	// negative, a default of one hour is used.
	Lifetime time.Duration
	// Now returns the current time. If nil, time.Now is used. It can be
	// injected to test expiry and key rotation.
	Now func() time.Time
}

func (h *CookieHandler) now() time.Time {
	if h.Now != nil {
		return h.Now()
	}
	return time.Now()
}

func (h *CookieHandler) lifetime() time.Duration {
	if h.Lifetime > 0 {
		return h.Lifetime
	}
	return cookieDefaultLifetime
}

// ServerCookie returns a fresh server cookie bound to clientCookie and the
// source address ip. clientCookie must be CookieClientLen bytes long.
func (h *CookieHandler) ServerCookie(clientCookie []byte, ip net.IP) ([]byte, error) {
	if len(clientCookie) != CookieClientLen {
		return nil, ErrCookieClient
	}
	if len(h.Secrets) == 0 {
		return nil, ErrCookieSecret
	}
	ipb := cookieIP(ip)
	if ipb == nil {
		return nil, ErrCookieAddr
	}
	sc := make([]byte, CookieServerLen)
	sc[0] = CookieVersion
	binary.BigEndian.PutUint32(sc[4:8], uint32(h.now().Unix()))
	copy(sc[8:], h.hash(h.Secrets[0], clientCookie, sc[:8], ipb))
	return sc, nil
}

// Cookie returns clientCookie followed by a fresh server cookie, ready to be
// used as the Cookie field of an EDNS0_COOKIE option in a response.
func (h *CookieHandler) Cookie(clientCookie []byte, ip net.IP) ([]byte, error) {
	sc, err := h.ServerCookie(clientCookie, ip)
	if err != nil {
		return nil, err
	}
	c := make([]byte, 0, CookieClientLen+CookieServerLen)
	c = append(c, clientCookie...)
	return append(c, sc...), nil
}

// Validate inspects a COOKIE option value received from the source address
// ip and reports its status. See CookieStatus for the possible verdicts and
// who is responsible for acting on them.
func (h *CookieHandler) Validate(cookie []byte, ip net.IP) CookieStatus {
	if len(cookie) == 0 {
		return CookieAbsent
	}
	if len(cookie) < CookieClientLen || len(cookie) > cookieMaxLen {
		return CookieInvalid
	}
	if len(cookie) == CookieClientLen {
		return CookieClientOnly
	}
	// A server cookie is present. Only the RFC 9018 format generated by
	// this handler can verify.
	if len(cookie) != CookieClientLen+CookieServerLen {
		return CookieInvalid
	}
	ipb := cookieIP(ip)
	if ipb == nil {
		return CookieInvalid
	}
	sc := cookie[CookieClientLen:]
	if sc[0] != CookieVersion || sc[1] != 0 || sc[2] != 0 || sc[3] != 0 {
		return CookieInvalid
	}
	ts := int64(binary.BigEndian.Uint32(sc[4:8]))
	age := h.now().Unix() - ts
	if age < 0 {
		return CookieInvalid
	}
	if age > int64(h.lifetime()/time.Second) {
		return CookieExpired
	}
	want := sc[8:]
	for _, secret := range h.Secrets {
		if subtle.ConstantTimeCompare(h.hash(secret, cookie[:CookieClientLen], sc[:8], ipb), want) == 1 {
			return CookieValid
		}
	}
	return CookieInvalid
}

// hash computes the server cookie hash over the client cookie, the server
// cookie header (Version | Reserved | Timestamp), the client IP address and
// the secret, in that order.
func (h *CookieHandler) hash(secret, clientCookie, header, ip []byte) []byte {
	f := fnv.New64a()
	f.Write(clientCookie)
	f.Write(header)
	f.Write(ip)
	f.Write(secret)
	return f.Sum(nil)
}

// cookieIP returns ip as 4 bytes for IPv4 or 16 bytes for IPv6 addresses,
// or nil if ip is neither.
func cookieIP(ip net.IP) []byte {
	if v4 := ip.To4(); v4 != nil {
		return v4
	}
	return ip.To16()
}
